#!/bin/sh
set -eu
cd "$1"
if ! test -f .config; then make tinyconfig; fi
for option in 64BIT SMP X86_64 GENERIC_CPU LOCALVERSION_AUTO MODULES MODULE_UNLOAD BLOCK BLK_DEV MULTIUSER PRINTK BUG ELF_CORE BINFMT_ELF BINFMT_SCRIPT COREDUMP SYSCTL SYSVIPC POSIX_TIMERS HIGH_RES_TIMERS ADVISE_SYSCALLS MEMBARRIER KALLSYMS EXPERT FUTEX EPOLL SIGNALFD TIMERFD EVENTFD AIO IO_URING FHANDLE INOTIFY_USER FILE_LOCKING DNOTIFY RT_MUTEXES VM_EVENT_COUNTERS COMPAT_BRK PROC_FS PROC_SYSCTL SYSFS TMPFS TMPFS_POSIX_ACL SHMEM DEVTMPFS DEVTMPFS_MOUNT UNIX98_PTYS DEVPTS_MULTIPLE_INSTANCES TTY VT VT_CONSOLE VT_HW_CONSOLE_BINDING VGA_CONSOLE SERIAL_8250 SERIAL_8250_CONSOLE SERIAL_8250_PCI UNIX NET INET PACKET NETDEVICES NET_CORE ETHERNET PCI PCI_MSI PCI_QUIRKS PCI_LEGACY PCI_DIRECT NET_VENDOR_INTEL E1000 E1000E NET_VENDOR_REALTEK 8139TOO R8169 VIRTIO_MENU VIRTIO VIRTIO_PCI VIRTIO_PCI_LEGACY VIRTIO_NET VIRTIO_BLK VIRTIO_CONSOLE BLK_DEV_INITRD RD_GZIP RD_XZ RD_ZSTD ATA ATA_PIIX SATA_AHCI SCSI BLK_DEV_SD EXT4_FS EXT4_FS_POSIX_ACL EXT4_FS_SECURITY EXT4_USE_FOR_EXT2 JBD2 FS_MBCACHE FS_POSIX_ACL MSDOS_PARTITION EFI_PARTITION FAT_FS VFAT_FS NLS NLS_CODEPAGE_437 NLS_ISO8859_1 INPUT INPUT_EVDEV INPUT_KEYBOARD KEYBOARD_ATKBD INPUT_MOUSE MOUSE_PS2 SERIO SERIO_I8042 SERIO_LIBPS2 HID HID_GENERIC USB_SUPPORT USB USB_COMMON USB_XHCI_HCD USB_EHCI_HCD USB_OHCI_HCD USB_UHCI_HCD USB_HID USB_STORAGE FB FB_DEVICE FB_VESA FB_SIMPLE SYSFB SYSFB_SIMPLEFB FB_EFI FRAMEBUFFER_CONSOLE FONT_8x16 DRM DRM_BOCHS DRM_FBDEV_EMULATION DRM_SIMPLEDRM ACPI ACPI_BUTTON ACPI_PROCESSOR ACPI_THERMAL X86_ACPI_CPUFREQ CPU_FREQ CPU_FREQ_DEFAULT_GOV_SCHEDUTIL PM RTC_CLASS RTC_DRV_CMOS HW_RANDOM HW_RANDOM_VIRTIO CRYPTO CRYPTO_USER_API CRYPTO_USER_API_HASH CRYPTO_USER_API_SKCIPHER CRYPTO_AES CRYPTO_SHA256 CRYPTO_SHA1 CRYPTO_CCM CRYPTO_GCM WLAN WIRELESS CFG80211 CFG80211_WEXT MAC80211 RFKILL WLAN_VENDOR_ATH ATH_COMMON ATH9K ATH9K_PCI WLAN_VENDOR_REALTEK RTL8187 FW_LOADER SECURITY_DMESG_RESTRICT NETWORK_FILESYSTEMS NFS_FS NFS_V3 NFS_V4 SUNRPC LOCKD FONTS; do
 scripts/config --enable "$option"
done
scripts/config --disable LOCALVERSION_AUTO --disable DEBUG_KERNEL --disable DEBUG_INFO --disable DEBUG_INFO_DWARF_TOOLCHAIN_DEFAULT --disable SYSTEM_TRUSTED_KEYRING --disable SYSTEM_REVOCATION_LIST --disable MODULE_SIG --disable WERROR --disable DRM_I915 --disable DRM_AMDGPU --disable DRM_NOUVEAU --disable CFG80211_REQUIRE_SIGNED_REGDB --disable CFG80211_USE_KERNEL_REGDB_KEYS --disable SECURITY_DMESG_RESTRICT --disable NO_HZ_FULL
scripts/config --set-str LOCALVERSION '-marrow' --set-str DEFAULT_HOSTNAME marrow --set-str SYSTEM_TRUSTED_KEYS '' --set-str SYSTEM_REVOCATION_KEYS '' --set-val NR_CPUS 8 --set-val LOG_BUF_SHIFT 18
make olddefconfig

for option in VIRTIO_PCI VIRTIO_BLK VIRTIO_NET EXT4_FS ATH9K RTL8187 INPUT_EVDEV DRM_BOCHS; do
 grep -q "^CONFIG_${option}=y$" .config || { echo "Missing kernel requirement: $option" >&2; exit 1; }
done
